import{_ as n,o as s,c as e,am as l}from"./chunks/framework.CiF4W93w.js";const u=JSON.parse('{"title":"面试总结20203回答版","description":"","frontmatter":{"title":"面试总结20203回答版","excerpt":"面试总结20203回答版","date":"2024-03-18 17:11:09","updated":"2024-03-18 17:11:09"},"headers":[],"relativePath":"Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/面试总结20203回答版.md","filePath":"Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/面试总结20203回答版.md","lastUpdated":null}'),i={name:"Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/面试总结20203回答版.md"};function p(o,a,r,t,c,h){return s(),e("div",null,[...a[0]||(a[0]=[l(`<p>部分记录，后续使用了录音，手机进行复盘</p><h3 id="_20240318" tabindex="-1">20240318 <a class="header-anchor" href="#_20240318" aria-label="Permalink to &quot;20240318&quot;">​</a></h3><p>SpringCloud</p><h5 id="安全测评怎么做的" tabindex="-1">安全测评怎么做的 <a class="header-anchor" href="#安全测评怎么做的" aria-label="Permalink to &quot;安全测评怎么做的&quot;">​</a></h5><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240318224301.png" alt="image.png"></p><p>部分可能相关联内容</p><ol><li>代码安全审计</li></ol><ul><li><strong>静态代码分析</strong>：使用工具如SonarQube、Fortify或Checkmarx等对代码进行静态分析，以识别安全漏洞和不良编码习惯。</li><li><strong>依赖项扫描</strong>：利用工具如OWASP Dependency-Check或Snyk扫描项目依赖的库和框架，识别已知的安全漏洞。</li></ul><ol start="2"><li>认证与授权</li></ol><ul><li><strong>强制认证</strong>：确保所有服务都实施了强制的认证机制。可以使用Spring Security或OAuth2.0、JWT（JSON Web Tokens）等技术进行身份验证和授权。</li><li><strong>服务间通信安全</strong>：服务间通信应使用HTTPS或其他安全通道，确保数据传输过程中的加密。</li></ul><hr><h4 id="修复过哪些漏洞" tabindex="-1">修复过哪些漏洞 <a class="header-anchor" href="#修复过哪些漏洞" aria-label="Permalink to &quot;修复过哪些漏洞&quot;">​</a></h4><p>待完善</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240318224653.png" alt="image.png"></p><p>漏洞风险</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240318225618.png" alt="image.png"></p><h4 id="你熟悉springcloud-的哪些组件" tabindex="-1">你熟悉SpringCloud 的哪些组件 <a class="header-anchor" href="#你熟悉springcloud-的哪些组件" aria-label="Permalink to &quot;你熟悉SpringCloud 的哪些组件&quot;">​</a></h4><p>Nacos + OpenFeign</p><p>Nacos + Ribbon + Gateway + OpenFeign + Sentinel + xxl-job</p><h4 id="权限管理" tabindex="-1">权限管理 <a class="header-anchor" href="#权限管理" aria-label="Permalink to &quot;权限管理&quot;">​</a></h4><p>RBAC 模型 + SpringSecurity + 菜单权限管理</p><h4 id="项目授权你们项目是怎么做的" tabindex="-1">项目授权你们项目是怎么做的 <a class="header-anchor" href="#项目授权你们项目是怎么做的" aria-label="Permalink to &quot;项目授权你们项目是怎么做的&quot;">​</a></h4><p>认证授权 → 认证 + 授权 RBAC 模型（用户角色权限）</p><h4 id="gateway-模块" tabindex="-1">Gateway 模块 <a class="header-anchor" href="#gateway-模块" aria-label="Permalink to &quot;Gateway 模块&quot;">​</a></h4><p>工厂建模 + 认证授权 + 角色管理 放在同一个模块 → 网关</p><h4 id="身份认证你们怎么做的" tabindex="-1">身份认证你们怎么做的 <a class="header-anchor" href="#身份认证你们怎么做的" aria-label="Permalink to &quot;身份认证你们怎么做的&quot;">​</a></h4><p>Cookie ：<strong>存放在客户端，一般用来保存用户信息</strong></p><p>Session：<strong><code>Session</code> 的主要作用就是通过服务端记录用户的状态</strong></p><p>JWT（JSON Web Tokens） 方式</p><p>SpringSecurity + JWT 方式</p><p>API网关授权</p><p>Gateway 网关，集成授权和路由转发</p><p>路由z转发</p><p>SpringSecurity 框架作为登陆认证</p><p>JWT 作为授权令牌认证</p><p>API 网关集成，一般会使用 Gateway 集成认证和访问授权（单独认证访问）</p><h4 id="gateway-你们怎么用的" tabindex="-1">Gateway 你们怎么用的 <a class="header-anchor" href="#gateway-你们怎么用的" aria-label="Permalink to &quot;Gateway 你们怎么用的&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240318230829.png" alt="image.png"></p><h4 id="springcloud-和-springboot-有什么区别" tabindex="-1">SpringCloud 和 SpringBoot 有什么区别 <a class="header-anchor" href="#springcloud-和-springboot-有什么区别" aria-label="Permalink to &quot;SpringCloud 和 SpringBoot 有什么区别&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240318231016.png" alt="image.png"></p><hr><p>Vue</p><h4 id="组件-怎么传值" tabindex="-1">组件，怎么传值 <a class="header-anchor" href="#组件-怎么传值" aria-label="Permalink to &quot;组件，怎么传值&quot;">​</a></h4><p>在Vue中，组件之间的数据传递主要通过<code>props</code>和<code>events</code>来实现，这遵循了Vue推荐的单向数据流模式。父组件通过<code>props</code>向子组件传递数据，子组件通过事件向父组件发送消息。</p><h4 id="组件生命周期" tabindex="-1">组件生命周期 <a class="header-anchor" href="#组件生命周期" aria-label="Permalink to &quot;组件生命周期&quot;">​</a></h4><p>created 创建</p><p>monuted 挂载</p><p>destroyed 销毁</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240318231323.png" alt="image.png"></p><h4 id="你写过组件" tabindex="-1">你写过组件 <a class="header-anchor" href="#你写过组件" aria-label="Permalink to &quot;你写过组件&quot;">​</a></h4><p>一般有全局定义、局部定义</p><p>一般是局部定义，我的理解是：组件其实也是一个页面，他只是封装了部分内容，多了一些数据的入口，其他地方作为调用，传入数据，复用组件</p><p>组件之间会使用 props 和事件 进行传值</p><p>引入：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/2e95c0317b36972805038cd94b9272c.jpg" alt="2e95c0317b36972805038cd94b9272c.jpg"></p><h4 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h4><p>插槽基本用法；</p><p><a href="https://cn.vuejs.org/guide/components/slots" target="_blank" rel="noreferrer">https://cn.vuejs.org/guide/components/slots</a></p><h4 id="模板-vue" tabindex="-1">模板 vue <a class="header-anchor" href="#模板-vue" aria-label="Permalink to &quot;模板 vue&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/4ba63e85ee39566a000bccaa0ce7968.png" alt="4ba63e85ee39566a000bccaa0ce7968.png"></p><hr><p>Docket</p><h4 id="docket-的网络模式有哪几种" tabindex="-1">Docket 的网络模式有哪几种 <a class="header-anchor" href="#docket-的网络模式有哪几种" aria-label="Permalink to &quot;Docket 的网络模式有哪几种&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Docker容器的网络模式定义了容器的网络堆栈如何与宿主机以及其他容器交互。Docker支持多种网络模式，包括：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 1. bridge（桥接模式）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 默认网络模式。</span></span>
<span class="line"><span>- 当容器运行在桥接模式下，Docker会将容器连接到一个内部网络上，它通过一个虚拟桥接网络在宿主机上进行通信。</span></span>
<span class="line"><span>- 容器拥有自己的IP地址，并且可以与同一网络上的其他容器通信。</span></span>
<span class="line"><span>- 如果要从外部访问容器，需要配置端口映射。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 2. host（主机模式）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 容器共享宿主机的网络命名空间，直接使用宿主机的网络。</span></span>
<span class="line"><span>- 容器不会被隔离在自己的网络内，而是直接使用宿主机的IP和端口。</span></span>
<span class="line"><span>- 这种模式可以提高网络性能，但减少了网络隔离。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 3. none（无网络模式）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 容器拥有自己的网络命名空间，但不会为容器配置网络接口。</span></span>
<span class="line"><span>- 通常用于测试或者需要完全隔离网络的应用。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 4. container（容器网络模式）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 允许一个容器共享另一个容器的网络命名空间。</span></span>
<span class="line"><span>- 这意味着它们会共享同一个IP地址和端口范围。</span></span>
<span class="line"><span>- 适用于一组紧密耦合的容器，它们需要通过localhost互相通信。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 5. overlay（覆盖网络模式）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 专为Docker Swarm集群设计，支持不同Docker守护进程上的容器间的网络通信。</span></span>
<span class="line"><span>- 使用分布式数据存储来保持网络状态，跨多个宿主机提供容器网络互连。</span></span>
<span class="line"><span>- 允许Swarm服务之间的安全通信。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 6. macvlan（MACVLAN网络模式）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 允许给容器分配MAC地址，使其看起来像是物理网络上的一个物理设备。</span></span>
<span class="line"><span>- 对于需要直接与物理网络交互的容器非常有用。</span></span>
<span class="line"><span>- 可以让容器直接出现在物理网络上，而不是通过Docker主机进行NAT转换。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每种网络模式都有其特定的用例和性能特点。选择合适的网络模式取决于应用的具体需求，例如对性能、安全或隔离级别的要求。</span></span></code></pre></div><h4 id="讲一下-docket-compose" tabindex="-1">讲一下 Docket compose <a class="header-anchor" href="#讲一下-docket-compose" aria-label="Permalink to &quot;讲一下 Docket compose&quot;">​</a></h4><p>Docker Compose是一个用于定义和运行多容器Docker应用程序的工具。</p><p>通过使用YAML文件来配置应用服务，可以通过单个命令快速启动和停止与应用相关的所有容器。这样不仅简化了容器管理过程，还能确保在不同环境中的一致性运行。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240318231821.png" alt="image.png"></p><h4 id="讲一下容器编排调度" tabindex="-1">讲一下容器编排调度 <a class="header-anchor" href="#讲一下容器编排调度" aria-label="Permalink to &quot;讲一下容器编排调度&quot;">​</a></h4><p>Nginx</p><h4 id="文件从服务器a-的一个文件夹-到-服务器-b-使用什么命令可以搞" tabindex="-1">文件从服务器A 的一个文件夹 到 服务器 B 使用什么命令可以搞 <a class="header-anchor" href="#文件从服务器a-的一个文件夹-到-服务器-b-使用什么命令可以搞" aria-label="Permalink to &quot;文件从服务器A 的一个文件夹 到 服务器 B 使用什么命令可以搞&quot;">​</a></h4><p>反向代理、配置共享文件夹？</p><p>Redis</p><h4 id="redis-缓存更新是怎么做的" tabindex="-1">Redis 缓存更新是怎么做的 <a class="header-anchor" href="#redis-缓存更新是怎么做的" aria-label="Permalink to &quot;Redis 缓存更新是怎么做的&quot;">​</a></h4><ul><li>全量更新</li></ul><p>Spring</p><h4 id="讲一下-aop-以及具体如何使用的" tabindex="-1">讲一下 AOP，以及具体如何使用的 <a class="header-anchor" href="#讲一下-aop-以及具体如何使用的" aria-label="Permalink to &quot;讲一下 AOP，以及具体如何使用的&quot;">​</a></h4><p>日志，事务，权限</p><p>织入点，前置通知，后置通知，环绕通知</p><p>这个还可以写一下 AOP + Redis 实现延迟双删操作</p><h3 id="_20240325" tabindex="-1">20240325 <a class="header-anchor" href="#_20240325" aria-label="Permalink to &quot;20240325&quot;">​</a></h3><p>K8s、Dubbo、NIO</p><p>项目，基础，场景题考察一下你，看一下你的个人能力和思考方式，给出一个OK的策略</p><ul><li>1、项目上没用什么好问的（改简历）</li><li>2、项目经历太薄弱了点，没什么东西，比大部分校招生的项目经历介绍还要差一些</li></ul><h4 id="jvm-docker的使用" tabindex="-1">jvm docker的使用 <a class="header-anchor" href="#jvm-docker的使用" aria-label="Permalink to &quot;jvm docker的使用&quot;">​</a></h4><h4 id="问了一下nio" tabindex="-1">问了一下nio <a class="header-anchor" href="#问了一下nio" aria-label="Permalink to &quot;问了一下nio&quot;">​</a></h4><h4 id="问了一下mq的使用" tabindex="-1">问了一下mq的使用 <a class="header-anchor" href="#问了一下mq的使用" aria-label="Permalink to &quot;问了一下mq的使用&quot;">​</a></h4><h4 id="问了一下valatile" tabindex="-1">问了一下valatile <a class="header-anchor" href="#问了一下valatile" aria-label="Permalink to &quot;问了一下valatile&quot;">​</a></h4><h4 id="问了一下设计模式" tabindex="-1">问了一下设计模式 <a class="header-anchor" href="#问了一下设计模式" aria-label="Permalink to &quot;问了一下设计模式&quot;">​</a></h4><h3 id="_20240407" tabindex="-1">20240407 <a class="header-anchor" href="#_20240407" aria-label="Permalink to &quot;20240407&quot;">​</a></h3><h4 id="说一下-hashmap-的底层实现" tabindex="-1">说一下 HashMap 的底层实现 <a class="header-anchor" href="#说一下-hashmap-的底层实现" aria-label="Permalink to &quot;说一下 HashMap 的底层实现&quot;">​</a></h4><ul><li>1.7 头插法会导致循环链表问题 <ul><li>由于每次插入都会改变链表的顺序，这可能会导致长时间的性能下降</li></ul></li><li>1.8 改为了尾插法，在并发修改时减少了循环链表出现的风险</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240311195612.png" alt="image.png"></p><h4 id="说一下-mysql-的慢查询分析-以及索引优化注意的地方" tabindex="-1">说一下 mysql 的慢查询分析，以及索引优化注意的地方 <a class="header-anchor" href="#说一下-mysql-的慢查询分析-以及索引优化注意的地方" aria-label="Permalink to &quot;说一下 mysql 的慢查询分析，以及索引优化注意的地方&quot;">​</a></h4><ul><li>看是否索引失效</li><li>看是否索引命中</li><li>看是否索引合理</li></ul><h4 id="说一下什么时候会索引失效" tabindex="-1">说一下什么时候会索引失效 <a class="header-anchor" href="#说一下什么时候会索引失效" aria-label="Permalink to &quot;说一下什么时候会索引失效&quot;">​</a></h4><ul><li>like &#39;&#39; <ul><li>使用<code>LIKE</code>操作符进行模糊匹配，且匹配模式以通配符（如<code>%</code>或<code>_</code>）开头时，</li></ul></li><li>or <ul><li>当使用<code>OR</code>连接多个条件时，如果所有条件列都被索引，那么索引有可能被使用；但如果其中一列没有被索引，那么即使其他列有索引，索引也可能不被使用</li></ul></li><li>索引字段使用 is null，is not null，索引可能失效</li><li>表达式进行计算</li></ul><h4 id="说一下-mysql-的隔离级别" tabindex="-1">说一下 mysql 的隔离级别 <a class="header-anchor" href="#说一下-mysql-的隔离级别" aria-label="Permalink to &quot;说一下 mysql 的隔离级别&quot;">​</a></h4><ul><li>重复读未提交 脏读</li><li>重复读已提交 可重复读</li><li>可重复读 幻读</li><li>串行化</li></ul><h4 id="说一下你在创建数据库的表有什么注意的地方-以及你们项目组的字段规范说一下" tabindex="-1">说一下你在创建数据库的表有什么注意的地方，以及你们项目组的字段规范说一下 <a class="header-anchor" href="#说一下你在创建数据库的表有什么注意的地方-以及你们项目组的字段规范说一下" aria-label="Permalink to &quot;说一下你在创建数据库的表有什么注意的地方，以及你们项目组的字段规范说一下&quot;">​</a></h4><ul><li>创建，常见的字段, 创建人，创建时间，更新人，更新时间，uda 额外字段</li><li>字段类型和字段长度要合理设置，比如说 vin 要设置到 char 17；varchar</li><li>is 开头不太好</li></ul><h4 id="说一下死锁你们怎么处理的" tabindex="-1">说一下死锁你们怎么处理的 <a class="header-anchor" href="#说一下死锁你们怎么处理的" aria-label="Permalink to &quot;说一下死锁你们怎么处理的&quot;">​</a></h4><h4 id="装饰器设计模式和组合模式的区别你讲一下-怎么用的" tabindex="-1">装饰器设计模式和组合模式的区别你讲一下，怎么用的 <a class="header-anchor" href="#装饰器设计模式和组合模式的区别你讲一下-怎么用的" aria-label="Permalink to &quot;装饰器设计模式和组合模式的区别你讲一下，怎么用的&quot;">​</a></h4><h4 id="比如说我有一堆无序的元素-我想要让他放入到一个先进先出的集合中-你会怎么做" tabindex="-1">比如说我有一堆无序的元素，我想要让他放入到一个先进先出的集合中，你会怎么做 <a class="header-anchor" href="#比如说我有一堆无序的元素-我想要让他放入到一个先进先出的集合中-你会怎么做" aria-label="Permalink to &quot;比如说我有一堆无序的元素，我想要让他放入到一个先进先出的集合中，你会怎么做&quot;">​</a></h4><h4 id="说一下-mysql-中的关键字优先级" tabindex="-1">说一下 mysql 中的关键字优先级 <a class="header-anchor" href="#说一下-mysql-中的关键字优先级" aria-label="Permalink to &quot;说一下 mysql 中的关键字优先级&quot;">​</a></h4><h4 id="说一下-spring-的传播事务" tabindex="-1">说一下 spring 的传播事务 <a class="header-anchor" href="#说一下-spring-的传播事务" aria-label="Permalink to &quot;说一下 spring 的传播事务&quot;">​</a></h4>`,106)])])}const b=n(i,[["render",p]]);export{u as __pageData,b as default};
